class DeleteConfirmDialog {
    constructor() {
        this.dialog = document.getElementById('delete-dialog');
        this.trigger = document.querySelector('.trigger');
        this.closeBtn = this.dialog.querySelector('[data-close]');
        this.confirmBtn = this.dialog.querySelector('[data-confirm]');

        this.init();
    }

    init() {
        if (!this.dialog || !this.trigger) {
            console.error('Delete dialog or trigger button not found');
            return;
        }

        // Open dialog on trigger click
        this.trigger.addEventListener('click', () => this.openDialog());

        // Close dialog on cancel button
        this.closeBtn.addEventListener('click', () => this.closeDialog('cancel'));

        // Handle delete confirmation
        this.confirmBtn.addEventListener('click', () => this.handleDelete());

        // Close dialog on Escape key
        this.dialog.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                this.closeDialog('cancelled');
            }
        });

        // Close dialog when backdrop is clicked (if supported)
        this.dialog.addEventListener('click', (e) => {
            if (e.target === this.dialog) {
                this.closeDialog('backdrop-click');
            }
        });
    }

    openDialog() {
        // Show the modal
        this.dialog.showModal();

        // Set initial focus to the cancel button (safer than delete for accidental activation)
        this.closeBtn.focus();
    }

    closeDialog(reason) {
        this.dialog.close(reason);
        // Focus automatically returns to trigger for native <dialog>
    }

    handleDelete() {
        // Simulate deletion (in real app, would send API request)
        this.closeDialog('confirmed');

        // Show user feedback
        this.showFeedback('Image deleted successfully.');
    }

    showFeedback(message) {
        // Create and display a temporary feedback message
        const feedback = document.createElement('div');
        feedback.setAttribute('role', 'status');
        feedback.setAttribute('aria-live', 'polite');
        feedback.className = 'feedback-message';
        feedback.textContent = message;
        document.body.appendChild(feedback);

        // Auto-remove after 3 seconds
        setTimeout(() => {
            feedback.remove();
        }, 3000);
    }
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    new DeleteConfirmDialog();
});
